// src/domains/trade-groups/trade-groups.validation.ts
function parseCreateGroupBody(body) {
  const b2 = body;
  const raw = b2?.tradeIds;
  if (!Array.isArray(raw) || raw.length === 0) {
    return { ok: false, error: "tradeIds must be a non-empty array" };
  }
  const tradeIds = [];
  for (const id of raw) {
    if (typeof id !== "string" || id.length === 0) {
      return { ok: false, error: "Every tradeId must be a non-empty string" };
    }
    tradeIds.push(id);
  }
  if (new Set(tradeIds).size !== tradeIds.length) {
    return { ok: false, error: "tradeIds must not contain duplicates" };
  }
  return { ok: true, tradeIds };
}

// src/domains/trade-groups/trade-groups.routes.ts
function registerTradeGroupsRoutes(app2, requireAuth2) {
  app2.post(
    "/trade-groups",
    { preHandler: requireAuth2 },
    async (request, reply) => {
      const userId = request.session.userId;
      await finalizeDueGoals(userId);
      const parsed = parseCreateGroupBody(request.body);
      if (!parsed.ok) {
        return reply.code(400).send({ error: parsed.error });
      }
      const eligibility = await validateGroupEligibility(sql, userId, parsed.tradeIds);
      if (!eligibility.ok) {
        return reply.code(eligibility.status).send({ error: eligibility.error });
      }
      try {
        const createdId = await sql.begin(async (tx) => {
          const [group] = await tx`
            INSERT INTO manual_trade_groups (
              user_id, account_id, symbol, direction, group_date,
              planned_entry_price, planned_stop_price, planned_target_price
            ) VALUES (
              ${userId}::uuid,
              ${eligibility.accountId},
              ${eligibility.symbol},
              ${eligibility.direction},
              ${eligibility.groupDate},
              ${eligibility.plannedEntryPrice},
              ${eligibility.plannedStopPrice},
              ${eligibility.plannedTargetPrice}
            )
            RETURNING id
          `;
          const membersPayload = eligibility.orderedTradeIds.map((tid, i) => ({
            group_id: group.id,
            trade_id: tid,
            user_id: userId,
            ordinal: i + 1
          }));
          await tx`
            INSERT INTO manual_trade_group_members ${sql(membersPayload, "group_id", "trade_id", "user_id", "ordinal")}
          `;
          return group.id;
        });
        const result = await fetchGroupRow(createdId, userId);
        return reply.code(201).send(mapGroupRow(result.group, result.members));
      } catch (err) {
        const message = err instanceof Error ? err.message : "unknown error";
        app2.log.error({ err }, "manual trade group create failed");
        if (String(message).includes("manual_trade_group_members")) {
          return reply.code(409).send({
            error: "One of these trades was grouped concurrently. Please retry."
          });
        }
        return reply.code(500).send({ error: message });
      }
    }
  );
  app2.get(
    "/trade-groups",
    { preHandler: requireAuth2 },
    async (request, reply) => {
      const userId = request.session.userId;
      const groups = await fetchActiveGroupsForUser(userId);
      return reply.send(groups);
    }
  );
  app2.get(
    "/trade-groups/:id",
    { preHandler: requireAuth2 },
    async (request, reply) => {
      const userId = request.session.userId;
      const { id } = request.params;
      const existing = await fetchGroupRow(id, userId);
      if (!existing) return reply.code(404).send({ error: "group not found" });
      const metaMap = await fetchGroupJournalMeta([id]);
      const meta = metaMap.get(id) ?? { setupName: null, tags: [] };
      return reply.send(
        mapGroupRow(
          existing.group,
          existing.members,
          null,
          meta.setupName,
          meta.tags,
          metaMap.has(id)
        )
      );
    }
  );
  app2.delete(
    "/trade-groups/:id",
    { preHandler: requireAuth2 },
    async (request, reply) => {
      const userId = request.session.userId;
      await finalizeDueGoals(userId);
      const { id } = request.params;
      const existing = await fetchGroupRow(id, userId);
      if (!existing) {
        return reply.code(404).send({ error: "group not found" });
      }
      await sql.begin(async (tx) => {
        await tx`UPDATE manual_trade_groups SET status = 'archived', updated_at = now() WHERE id = ${id}::uuid AND user_id = ${userId}::uuid`;
        await tx`UPDATE manual_trade_group_members SET group_status = 'archived' WHERE group_id = ${id}::uuid`;
      });
      return reply.send({ ok: true });
    }
  );
  app2.patch(
    "/trade-groups/:id",
    { preHandler: requireAuth2 },
    async (request, reply) => {
      const userId = request.session.userId;
      await finalizeDueGoals(userId);
      const { id } = request.params;
      const existing = await fetchGroupRow(id, userId);
      if (!existing) return reply.code(404).send({ error: "group not found" });
      const body = request.body ?? {};
      if (body.plannedStopPrice === void 0 && body.plannedTargetPrice === void 0) {
        return reply.code(400).send({ error: "No updatable fields provided (plannedStopPrice, plannedTargetPrice)." });
      }
      const stop = body.plannedStopPrice;
      const target = body.plannedTargetPrice;
      if (stop !== void 0) {
        await sql`UPDATE manual_trade_groups SET planned_stop_price = ${stop}, planned_entry_price = NULL, plan_source = 'manual', updated_at = now() WHERE id = ${id}::uuid AND user_id = ${userId}::uuid`;
      }
      if (target !== void 0) {
        await sql`UPDATE manual_trade_groups SET planned_target_price = ${target}, planned_entry_price = NULL, plan_source = 'manual', updated_at = now() WHERE id = ${id}::uuid AND user_id = ${userId}::uuid`;
      }
      try {
        await recomputeGroupScore(id, userId);
      } catch (err) {
        app2.log.error({ err, groupId: id }, "group plan updated but score recompute failed");
        return reply.code(502).send({
          error: "Group plan saved, but the group execution score could not be refreshed. Retrying the save is safe.",
          code: "SCORE_RECOMPUTE_FAILED"
        });
      }
      const result = await fetchGroupRow(id, userId);
      const metaMap = await fetchGroupJournalMeta([id]);
      const meta = metaMap.get(id) ?? { setupName: null, tags: [] };
      return reply.send(
        mapGroupRow(
          result.group,
          result.members,
          null,
          meta.setupName,
          meta.tags,
          metaMap.has(id)
        )
      );
    }
  );
  registerTradeGroupsScreenshotRoutes(app2, requireAuth2);
}

