async function resolveTradeIds(rawIds, userId) {
  if (rawIds.length === 0) return [];
  const valid = await sql`
    SELECT id FROM trades
    WHERE id = ANY(${rawIds}::uuid[]) AND user_id = ${userId}::uuid
  `;
  const validSet = new Set(valid.map((r) => r.id));
  return rawIds.filter((id) => validSet.has(id));
}
function isReviewEmpty(r) {
  return r.bias === null && r.readiness === null && r.key_levels === null && r.setups === null && r.risk_limit === null && r.intention === null && r.day_notes === null && r.went_well === null && r.to_improve === null && r.tomorrow_focus === null && (r.flags === null || r.flags.length === 0);
}
async function ensureJournalDay(userId, date) {
  const existing = await sql`
    SELECT * FROM journal_days
    WHERE user_id = ${userId}::uuid AND journal_date = ${date}::date
  `;
  if (existing.length > 0) return existing[0];
  const inserted = await sql`
    INSERT INTO journal_days (user_id, journal_date)
    VALUES (${userId}::uuid, ${date}::date)
    ON CONFLICT (user_id, journal_date) DO NOTHING
    RETURNING *
  `;
  if (inserted.length > 0) return inserted[0];
  const refetched = await sql`
    SELECT * FROM journal_days
    WHERE user_id = ${userId}::uuid AND journal_date = ${date}::date
  `;
  return refetched[0];
}
function isValidDate(s) {
  return /^\d{4}-\d{2}-\d{2}$/.test(s) && !Number.isNaN(Date.parse(s));
}

