  if (s.metrics) renderMetricsSection(r, d);
  if (s.timePerformance) renderTimeSection(r, d);
  if (s.discipline) renderDisciplineSection(r, d);
  if (s.behavior) renderBehaviorSection(r, d);
  if (s.winloss) renderWinLossSection(r, d);
  if (s.risk) renderRiskSection(r, d);
  if (s.trades) renderTradesSection(r, d);
