function normalizeUploadUrl(rawUrl) {
  const path = rawUrl.split("?")[0].split("#")[0];
  if (!path.startsWith("/uploads/")) return null;
  if (path.includes("..") || path.includes("\0") || path.includes("\\")) {
    return null;
  }
  const normalized = path.replace(/\/+/g, "/");
  if (normalized !== path) return null;
  return normalized;
}
async function verifyScreenshotOwnership(sql2, userId, screenshotUrl) {
  const rows = await sql2`
    SELECT 1 AS owned
    WHERE EXISTS (
      SELECT 1 FROM trades
      WHERE user_id = ${userId}::uuid AND screenshot_url = ${screenshotUrl}
    )
    OR EXISTS (
      SELECT 1 FROM manual_trade_groups
      WHERE user_id = ${userId}::uuid AND screenshot_url = ${screenshotUrl}
    )
    LIMIT 1
  `;
  return rows.length > 0;
}

